query ItalianSearchLandingSource($skyfadeId: ID!, $publishedQuery: String!, $publishedAfter: String) {
  shop { name myshopifyDomain }
  historical: collectionByIdentifier(identifier: {handle: "mommy-and-me"}) { ...LandingCollection }
  dresses: collectionByIdentifier(identifier: {handle: "dresses"}) { ...LandingCollection }
  dedicated: collectionByIdentifier(identifier: {handle: "mother-daughter-matching-dresses"}) { ...LandingCollection }
  publishedCandidates: collections(first: 10, after: $publishedAfter, query: $publishedQuery) {
    nodes { id handle }
    pageInfo { hasNextPage endCursor }
  }
  skyfade: product(id: $skyfadeId) {
    id title handle status onlineStoreUrl productType
    translations(locale: "it") { key value locale outdated }
  }
}
fragment LandingCollection on Collection {
  id title handle sortOrder
  productsCount { count precision }
  hasSkyfade: hasProduct(id: $skyfadeId)
  translations(locale: "it") { key value locale outdated }
  products(first: 8, sortKey: COLLECTION_DEFAULT) {
    nodes { id title handle status onlineStoreUrl productType }
    pageInfo { hasNextPage endCursor }
  }
}
